import urllib.request,json,pathlib
BASE='http://127.0.0.1:17448'
routes={
'health':'/api/health',
'lifecycle':'/api/operator-lifecycle',
'watchdog':'/api/supervisor-watchdog?detect=0',
'cutover':'/api/projects/control-plane/cutover-r42/status',
'status':'/api/status'}
out={}
for key,route in routes.items():
 try:
  with urllib.request.urlopen(BASE+route,timeout=5) as r:d=json.load(r)
  top=sorted(d.keys()) if isinstance(d,dict) else []
  s={'ok':True,'keys':top[:48]}
  if key=='health':s.update({k:d.get(k) for k in ['state','reasons','blockers','codeReloadRequired','updatedAt'] if k in d})
  if key=='lifecycle':
   for k in ['mode','queuePaused','reconciliationRequired','reason','paused','state','contract','startup']: 
    if k in d:s[k]=d.get(k)
  if key=='watchdog':
   cfg=d.get('config') or {}
   if isinstance(cfg,dict):s['config']={k:cfg.get(k) for k in ['enabled','mode','allowAutonomousSend','autoContinueEnabled','highModeStrategy','enforceHighMode'] if k in cfg}
   for k in ['mode','enabled','allowAutonomousSend','queuePaused','reconciliationRequired']:
    if k in d:s[k]=d.get(k)
  if key=='cutover':
   cv=d.get('cutoverState') or {}
   if isinstance(cv,dict):s['cutoverState']={k:cv.get(k) for k in ['status','holdActive','updatedAt'] if k in cv}
  out[key]=s
 except Exception as e:out[key]={'ok':False,'errorType':type(e).__name__}
print(json.dumps({'snapshot':out,'noSend':True},ensure_ascii=True)[:5600])
